def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'D'
    if n == 3:
        return 'C'
    if n >= 99:
        return 'D'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    opp_def = sum(1 for o in opp if o == 'D')
    my_def = sum(1 for m in my if m == 'D')
    last_opp = opp[-1]
    last_my = my[-1]

    if opp_def > 0.6 * n or (n >= 5 and sum(1 for o in opp[-5:] if o == 'D') >= 4):
        return 'D'

    if opp_def <= 1 and my_def > 0:
        exploit = 0
        retaliate = 0
        for i in range(1, n):
            if my[i-1] == 'D':
                if opp[i] == 'C':
                    exploit += 1
                else:
                    retaliate += 1
        if exploit > retaliate:
            if n >= 98:
                return 'D'
            if last_my == 'C':
                return 'D'
            else:
                return 'C'

    if last_opp == 'D':
        if last_my == 'D':
            return 'C'
        else:
            if n >= 2 and my[-2] == 'D':
                return 'C'
            else:
                return 'D'
    else:
        if last_my == 'D':
            return 'C'
        return 'C'
